v.grid(); v.axes();
const a = 0, b = 4;
const f = x => 0.4 * Math.sin(1.1 * x) * x + 0.6 * x - 1.2;
const fa = f(a), fb = f(b);
const lo = Math.min(fa, fb), hi = Math.max(fa, fb);
const N = lo + (hi - lo) * (0.5 + 0.45 * Math.sin(t * P.speed));
v.fn(f, { color: H.colors.accent, width: 3 });
v.dot(a, fa, { r: 6, fill: H.colors.sub });
v.dot(b, fb, { r: 6, fill: H.colors.sub });
v.text("f(a)=" + fa.toFixed(2), a + 0.05, fa - 0.5, { color: H.colors.sub, size: 11 });
v.text("f(b)=" + fb.toFixed(2), b - 1.4, fb + 0.5, { color: H.colors.sub, size: 11 });
v.line(a, N, b, N, { color: H.colors.warn, width: 2, dash: [6, 5] });
v.text("N = " + N.toFixed(2), 4.05, N, { color: H.colors.warn, size: 12 });
let c = NaN;
let loX = a, hiX = b;
const incr = fb > fa;
for (let i = 0; i < 40; i++) {
  const mid = 0.5 * (loX + hiX);
  const fm = f(mid);
  if ((incr && fm < N) || (!incr && fm > N)) loX = mid; else hiX = mid;
  c = mid;
}
v.line(c, -3, c, N, { color: H.colors.good, width: 1, dash: [3, 3] });
